#include <iostream>
#include <queue>
#include <vector>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, f;
    cin >> n >> f;

    vector<string> grid(n);
    for (int i = 0; i < n; i++) cin >> grid[i];

    vector<vector<bool>> vis(n, vector<bool>(n, false));
    queue<pair<int, int>> q;

    // A lava só começa se a posição inicial satisfizer a condição de altura
    if (grid[0][0] - '0' <= f) {
        vis[0][0] = true;
        grid[0][0] = '*';
        q.push(make_pair(0, 0));
    }

    const int dx[4] = {0, 0, 1, -1};
    const int dy[4] = {1, -1, 0, 0};

    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n &&
                !vis[nx][ny] && grid[nx][ny] - '0' <= f) {
                vis[nx][ny] = true;
                grid[nx][ny] = '*';
                q.push(make_pair(nx, ny));
            }
        }
    }

    for (int i = 0; i < n; i++) cout << grid[i] << '\n';

    return 0;
}
